1	package ports
2	
3	import (
4		"errors"
5		"os"
6		"strconv"
7		"strings"
8		"testing"
9	)
10	
11	// ── Kill goes through procOS ─────────────────────────────────────────────────
12	
13	// Kill's only way to a signal is procOS.kill: that is what lets a test observe
14	// it, and what lets the guard stop a real one.
15	func TestKillSendsThroughProcOS(t *testing.T) {
16		fake := useFakeOS(t, 100, 99, "linux")
17	
18		if err := Kill("4242", IdentityForTest(1)); err != nil {
19			t.Fatalf("Kill(4242) = %v, want nil", err)
20		}
21		if len(fake.kills) != 1 || fake.kills[0] != 4242 {
22			t.Errorf("procOS.kill was called with %v, want [4242]", fake.kills)
23		}
24	}
25	
26	// ── The PID the kernel reads is not the PID the string says ──────────────────
27	
28	// The kernel reads the low 32 bits of the PID (pidfd_open, kill, OpenProcess
29	// all take 32 bits), so 1<<32+1 is PID 1 to it while an int comparison sees
30	// something else, and 4294967295 is kill(-1, SIGKILL): everything the user may
31	// signal. Kill and ProtectionOf share one parser that accepts only a canonical
32	// decimal in the int32 range (DEVDESK-708, criterion 4). Anything else is "not
33	// a process id", never a ProtectedError, and never reaches the OS.
34	func TestKillRefusesAPIDOutsideInt32OrNotCanonical(t *testing.T) {
35		const self, parent = 100, 99
36		cases := []struct {
37			name string
38			goos string
39			pid  string
40		}{
41			{"kill(-1) once truncated to 32 bits", "linux", "4294967295"},
42			{"PID 1 once truncated to 32 bits", "linux", "4294967297"},
43			{"one past int32", "linux", "2147483648"},
44			{"2^32, PID 0 once truncated", "linux", "4294967296"},
45			{"DevDesk itself once truncated", "linux", strconv.FormatInt(1<<32+int64(self), 10)},
46			{"the parent once truncated", "linux", strconv.FormatInt(1<<32+int64(parent), 10)},
47			{"the parent once truncated, far above", "linux", strconv.FormatInt(1<<40+int64(parent), 10)},
48			{"overflows even int64", "linux", "99999999999999999999"},
49			{"negative below int32", "linux", "-2147483649"},
50			{"explicit plus sign", "linux", "+5"},
51			{"leading zeros", "linux", "007"},
52			{"negative zero", "linux", "-0"},
53			{"leading space", "linux", " 5"},
54			{"trailing space", "linux", "5 "},
55			{"2^32 on Windows, the Idle process once truncated", "windows", "4294967296"},
56			{"2^32+4 on Windows, System once truncated", "windows", "4294967300"},
57			{"DevDesk itself once truncated on Windows", "windows", strconv.FormatInt(1<<32+int64(self), 10)},
58		}
59		for _, tc := range cases {
60			t.Run(tc.name, func(t *testing.T) {
61				fake := useFakeOS(t, self, parent, tc.goos)
62	
63				err := Kill(tc.pid, IdentityForTest(1))
64				if err == nil {
65					t.Errorf("Kill(%q) returned no error", tc.pid)
66				} else {
67					var perr *ProtectedError
68					if errors.As(err, &perr) {
69						t.Errorf("Kill(%q) = %v, a ProtectedError: the value is not a process id at all", tc.pid, err)
70					}
71					if !strings.Contains(err.Error(), "not a process id") {
72						t.Errorf("Kill(%q) = %q, want it to say %q", tc.pid, err.Error(), "not a process id")
73					}
74				}
75				if len(fake.kills) != 0 {
76					t.Errorf("procOS.kill was called with %v for %q", fake.kills, tc.pid)
77				}
78				if got := ProtectionOf(tc.pid); got != Unprotected {
79					t.Errorf("ProtectionOf(%q) = %v, want Unprotected", tc.pid, got)
80				}
81			})
82		}
83	}
84	
85	// The parser must not over-refuse: the largest int32 is a canonical PID and
86	// reaches the OS.
87	func TestKillAcceptsTheLargestInt32PID(t *testing.T) {
88		fake := useFakeOS(t, 100, 99, "linux")
89	
90		if got := ProtectionOf("2147483647"); got != Unprotected {
91			t.Errorf("ProtectionOf(2147483647) = %v, want Unprotected", got)
92		}
93		if err := Kill("2147483647", IdentityForTest(1)); err != nil {
94			t.Fatalf("Kill(2147483647) = %v, want nil", err)
95		}
96		if len(fake.kills) != 1 || fake.kills[0] != 2147483647 {
97			t.Errorf("procOS.kill was called with %v, want [2147483647]", fake.kills)
98		}
99	}
100	
101	// The Ports tab reads the failure with errors.Is (permission, already gone): the
102	// wrapping must keep the cause reachable.
103	func TestKillWrapsTheOSErrorSoTheUICanClassifyIt(t *testing.T) {
104		for _, cause := range []error{os.ErrPermission, os.ErrProcessDone} {
105			t.Run(cause.Error(), func(t *testing.T) {
106				fake := useFakeOS(t, 100, 99, "linux")
107				fake.killErr = cause
108	
109				err := Kill("4242", IdentityForTest(1))
110				if err == nil {
111					t.Fatal("Kill returned nil although the OS refused")
112				}
113				if !errors.Is(err, cause) {
114					t.Errorf("errors.Is(%v, %v) = false: the cause was not wrapped with %%w", err, cause)
115				}
116			})
117		}
118	}
