1	package ports
2	
3	import (
4		"errors"
5		"os"
6		"runtime"
7		"testing"
8	)
9	
10	// The real readers (DEVDESK-709, criterion 1, the system part). They read; they
11	// never signal.
12	
13	func skipUnlessIdentityIsReadable(t *testing.T) {
14		t.Helper()
15		switch runtime.GOOS {
16		case "linux", "darwin", "windows":
17		default:
18			t.Skipf("no identity reader on %s: every row there is unverifiable", runtime.GOOS)
19		}
20	}
21	
22	func TestRealIdentityOfThisProcessIsStable(t *testing.T) {
23		skipUnlessIdentityIsReadable(t)
24	
25		first, err := realOS{}.identity(os.Getpid())
26		if err != nil {
27			t.Fatalf("reading the identity of this process: %v", err)
28		}
29		second, err := realOS{}.identity(os.Getpid())
30		if err != nil {
31			t.Fatalf("reading it again: %v", err)
32		}
33		if first != second {
34			t.Errorf("the identity of a running process changed between two reads: %d then %d", first, second)
35		}
36	}
37	
38	// A PID above the default Linux pid_max has no process: the reader says so with
39	// the sentinel the UI turns into "no longer running", not with a generic error.
40	func TestRealIdentityOfAMissingPIDSaysGone(t *testing.T) {
41		if runtime.GOOS != "linux" {
42			t.Skip("the /proc reader is Linux only")
43		}
44		_, err := realOS{}.identity(unreachablePID)
45		if !errors.Is(err, os.ErrProcessDone) {
46			t.Errorf("identity(%d) = %v, want errors.Is os.ErrProcessDone", unreachablePID, err)
47		}
48	}
49	
50	// The identity is what tells two holders of a PID apart, so a child must not
51	// read like its parent.
52	func TestRealIdentityOfAChildDiffersFromItsParent(t *testing.T) {
53		if runtime.GOOS != "linux" {
54			t.Skip("the child helper of this package is exercised on Linux only")
55		}
56		child := startHelperChild(t)
57	
58		own, err := realOS{}.identity(os.Getpid())
59		if err != nil {
60			t.Fatalf("reading the identity of this process: %v", err)
61		}
62		theirs, err := realOS{}.identity(child.pid)
63		if err != nil {
64			t.Fatalf("reading the identity of the child %d: %v", child.pid, err)
65		}
66		if own == theirs {
67			t.Errorf("the child and its parent read the same identity %d", own)
68		}
69	}
70	
71	// The parsing is the same code path as the reader: /proc/self/stat read by hand
72	// and parsed must give what the reader gives.
73	func TestRealIdentityMatchesProcSelfStat(t *testing.T) {
74		if runtime.GOOS != "linux" {
75			t.Skip("/proc/self/stat is Linux only")
76		}
77		raw, err := os.ReadFile("/proc/self/stat")
78		if err != nil {
79			t.Skipf("/proc is not readable here: %v", err)
80		}
81		want, err := parseStartTicks(raw)
82		if err != nil {
83			t.Fatalf("parseStartTicks(/proc/self/stat) = %v; the parser does not read a real line", err)
84		}
85		got, err := realOS{}.identity(os.Getpid())
86		if err != nil {
87			t.Fatalf("identity(self) = %v", err)
88		}
89		if got != want {
90			t.Errorf("identity(self) = %d, /proc/self/stat says %d", got, want)
91		}
92	}
