1	package ports
2	
3	import (
4		"fmt"
5		"go/ast"
6		"go/parser"
7		"go/token"
8		"os"
9		"path/filepath"
10		"strconv"
11		"strings"
12		"testing"
13	)
14	
15	// unreachablePID is above the default Linux pid_max (4194304), so even a guard
16	// that failed to stop a signal would have no process to reach.
17	const unreachablePID = 4194305
18	
19	// recoverPanic runs f and returns what it panicked with, or nil.
20	func recoverPanic(f func()) (v any) {
21		defer func() { v = recover() }()
22		f()
23		return nil
24	}
25	
26	// ── Run-time guard ───────────────────────────────────────────────────────────
27	
28	// A test binary that did not ask for a real signal must not send one: the
29	// panic is what makes a test that forgot to substitute procOS fail loudly
30	// instead of killing something on the developer's machine.
31	func TestARealSignalInATestBinaryPanics(t *testing.T) {
32		if realSignalsAllowed.Load() {
33			t.Fatal("real signals are allowed at the start of a test; a previous test leaked allowRealSignals")
34		}
35		got := recoverPanic(func() { _ = realOS{}.kill(unreachablePID, IdentityForTest(1)) })
36		if got == nil {
37			t.Fatal("realOS.kill did not panic in a test binary that did not allow real signals")
38		}
39		msg := fmt.Sprint(got)
40		for _, want := range []string{"DEVDESK-708", strconv.Itoa(unreachablePID)} {
41			if !strings.Contains(msg, want) {
42				t.Errorf("panic message %q does not contain %q", msg, want)
43			}
44		}
45	}
46	
47	// Kill reaches the signal through the default procOS: with no substitution, a
48	// test calling Kill must hit the guard, not the machine.
49	func TestKillWithoutASubstitutedProcOSHitsTheGuard(t *testing.T) {
50		if _, ok := procOS.(realOS); !ok {
51			t.Fatalf("procOS defaults to %T, want realOS", procOS)
52		}
53		got := recoverPanic(func() { _ = Kill(strconv.Itoa(unreachablePID), IdentityForTest(1)) })
54		if got == nil {
55			t.Fatal("Kill reached a real signal in a test binary without allowRealSignals")
56		}
57		if !strings.Contains(fmt.Sprint(got), "DEVDESK-708") {
58			t.Errorf("panic = %v, want a message naming DEVDESK-708", got)
59		}
60	}
61	
62	// allowRealSignals is scoped to the test that calls it.
63	func TestAllowRealSignalsIsScopedToTheTest(t *testing.T) {
64		t.Run("inner", func(t *testing.T) {
65			allowRealSignals(t)
66			if !realSignalsAllowed.Load() {
67				t.Error("allowRealSignals did not allow real signals")
68			}
69		})
70		if realSignalsAllowed.Load() {
71			t.Error("real signals are still allowed after the test that asked for them ended")
72		}
73	}
74	
75	// ── Static guard ─────────────────────────────────────────────────────────────
76	
77	// signalCalls are the names whose call is a way to end or signal a process.
78	// Matched on the selector name, whatever the receiver: p.Kill(), p.Signal(),
79	// os.FindProcess, syscall.Kill, unix.Kill, windows.TerminateProcess.
80	var signalCalls = map[string]bool{
81		"FindProcess":      true,
82		"Kill":             true,
83		"Signal":           true,
84		"TerminateProcess": true,
85	}
86	
87	// TestOnlyRealOSSendsASignal: (realOS).kill is the one place of the package
88	// that signals a process, and its first statement is the run-time guard.
89	//
90	// Limits: an import alias is not resolved (the selector name is what is read),
91	// and another package or an external binary is not seen; the Ports tab reaches
92	// this package only through Kill.
93	func TestOnlyRealOSSendsASignal(t *testing.T) {
94		entries, err := os.ReadDir(".")
95		if err != nil {
96			t.Fatalf("reading the package directory: %v", err)
97		}
98		fset := token.NewFileSet()
99		foundRealOSKill := false
100		for _, e := range entries {
101			name := e.Name()
102			if e.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
103				continue
104			}
105			f, err := parser.ParseFile(fset, filepath.Join(".", name), nil, parser.SkipObjectResolution)
106			if err != nil {
107				t.Fatalf("parsing %s: %v", name, err)
108			}
109			for _, decl := range f.Decls {
110				fn, ok := decl.(*ast.FuncDecl)
111				if !ok || fn.Body == nil {
112					continue
113				}
114				if isRealOSKill(fn) {
115					foundRealOSKill = true
116					checkGuardIsFirst(t, fset, fn)
117					continue
118				}
119				reportSignalCalls(t, fset, fn)
120			}
121		}
122		if !foundRealOSKill {
123			t.Error("no method (realOS).kill in the package: the single point that sends a signal is missing")
124		}
125	}
126	
127	// isRealOSKill reports whether fn is the method `func (realOS) kill(...)`.
128	func isRealOSKill(fn *ast.FuncDecl) bool {
129		if fn.Recv == nil || len(fn.Recv.List) != 1 || fn.Name.Name != "kill" {
130			return false
131		}
132		typ := fn.Recv.List[0].Type
133		if star, ok := typ.(*ast.StarExpr); ok {
134			typ = star.X
135		}
136		id, ok := typ.(*ast.Ident)
