308	
309	const helperEnv = "DEVDESK_PORTS_HELPER"
310	
311	// TestHelperProcessSleeps is not a test: it is the body of the child process the
312	// tests below start from this very binary. It does nothing unless the parent set
313	// the variable.
314	func TestHelperProcessSleeps(t *testing.T) {
315		if os.Getenv(helperEnv) != "1" {
316			t.Skip("helper process of the real-child tests")
317		}
318		time.Sleep(time.Minute)
319	}
320	
321	// helperChild is a process the test started itself and always waits for, so it
322	// leaves neither a zombie nor an orphan.
323	type helperChild struct {
324		cmd     *exec.Cmd
325		pid     int
326		done    chan struct{}
327		waitErr error // valid once done is closed
328	}
329	
330	// startHelperChild starts the test binary on the helper above. Its cleanup ends
331	// and waits for the child: that signal is the test's, aimed at its own child,
332	// through os/exec and not through the package under test.
333	func startHelperChild(t *testing.T) *helperChild {
334		t.Helper()
335		cmd := exec.Command(os.Args[0], "-test.run=^TestHelperProcessSleeps$")
336		cmd.Env = append(os.Environ(), helperEnv+"=1")
337		if err := cmd.Start(); err != nil {
338			t.Fatalf("starting the helper process: %v", err)
339		}
340		c := &helperChild{cmd: cmd, pid: cmd.Process.Pid, done: make(chan struct{})}
341		go func() {
342			c.waitErr = cmd.Wait()
343			close(c.done)
344		}()
345		t.Cleanup(func() {
346			_ = cmd.Process.Kill() // an error here only says the child already ended
347			select {
348			case <-c.done:
349			case <-time.After(10 * time.Second):
350				t.Errorf("the helper process %d did not exit and could not be waited for", c.pid)
351			}
352		})
353		// Never signal anything that is not the child this test started.
354		if c.pid <= 1 || c.pid == os.Getpid() || c.pid == os.Getppid() {
355			t.Fatalf("the helper process has PID %d (self %d, parent %d): refusing to signal it", c.pid, os.Getpid(), os.Getppid())
356		}
357		return c
358	}
359	
360	// running reports whether the child has not exited, without blocking.
361	func (c *helperChild) running() bool {
362		select {
363		case <-c.done:
364			return false
365		default:
366			return true
367		}
368	}
369	
370	// identityOf reads the child's real identity.
371	func (c *helperChild) identityOf(t *testing.T) Identity {
372		t.Helper()
373		raw, err := realOS{}.identity(c.pid)
374		if err != nil {
375			t.Fatalf("reading the identity of the helper process %d: %v", c.pid, err)
376		}
377		return IdentityForTest(raw)
378	}
