455	// TestKillOfAnExitedChildSendsNothing: the listed process is gone. Either the
456	// PID is free (no process) or it was taken by another process (a different
457	// identity); a signal is never sent, and Kill never reports success.
458	func TestKillOfAnExitedChildSendsNothing(t *testing.T) {
459		if runtime.GOOS != "linux" {
